-- Run ONCE in the existing production D1 Console after setup-fines.sql.
-- Preserves attendance/fines. ALTER TABLE statements must not be repeated.
CREATE TABLE `members` (
	`id` text PRIMARY KEY NOT NULL,
	`username` text NOT NULL,
	`name` text NOT NULL,
	`password_hash` text NOT NULL,
	`password_salt` text NOT NULL,
	`active` integer DEFAULT 1 NOT NULL,
	`must_change_password` integer DEFAULT 1 NOT NULL,
	`session_version` integer DEFAULT 0 NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL
);

CREATE UNIQUE INDEX `members_username_unique` ON `members` (`username`);
CREATE UNIQUE INDEX `members_name_unique` ON `members` (`name`);
ALTER TABLE `attendance` ADD `owner_id` text;
ALTER TABLE `attendance` ADD `admin_record` integer DEFAULT 0 NOT NULL;
-- One-time class bootstrap. Existing accounts/passwords are never overwritten.

-- Attach legacy records to their member account; keep old displayed name aliases.
UPDATE attendance SET owner_id = (SELECT id FROM members WHERE members.name = CASE WHEN attendance.name = '이주연' THEN '이주언' ELSE attendance.name END) WHERE owner_id IS NULL;
